import { ProfilePatch } from './types';

const ALLOWED_KEYS = new Set<PropertyKey>(['displayName', 'tags']);
const MAX_NAME_LENGTH = 40;
const MAX_TAGS = 5;
const MAX_TAG_LENGTH = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

/** Length in Unicode code points, so astral characters count once. */
function charLength(value: string): number {
  let count = 0;
  for (const _ of value) count++;
  return count;
}

/** Reads an own data property without invoking getters. */
function readOwn(source: object, key: string): { present: false } | { present: true; value: unknown } {
  const descriptor = Object.getOwnPropertyDescriptor(source, key);
  if (descriptor === undefined) return { present: false };
  if (!('value' in descriptor)) invalid();
  return { present: true, value: descriptor.value };
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') invalid();
  const trimmed = value.trim();
  const length = charLength(trimmed);
  if (length < 1 || length > MAX_NAME_LENGTH) invalid();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value)) invalid();
  const length = value.length;
  if (length > MAX_TAGS) invalid();
  const result: string[] = [];
  const seen = new Set<string>();
  for (let index = 0; index < length; index++) {
    const element = readOwn(value, String(index));
    if (!element.present || typeof element.value !== 'string') invalid();
    const trimmed = element.value.trim();
    const tagLength = charLength(trimmed);
    if (tagLength < 1 || tagLength > MAX_TAG_LENGTH || seen.has(trimmed)) invalid();
    seen.add(trimmed);
    result.push(trimmed);
  }
  return result;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) invalid();
  for (const key of Reflect.ownKeys(input)) if (!ALLOWED_KEYS.has(key)) invalid();

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  const rawName = readOwn(input, 'displayName');
  if (rawName.present) displayName = { kind: 'set', value: parseDisplayName(rawName.value) };
  const rawTags = readOwn(input, 'tags');
  if (rawTags.present) tags = { kind: 'set', value: parseTags(rawTags.value) };
  return { displayName, tags };
}
EOF
cat > src/service.ts <<'EOF'
import { Profile } from './types';
import { parseProfile } from './parser';
export class ProfileService {
  constructor(readonly profile: Profile) {}
  patch(input: unknown): Profile {
    // Parse and validate fully before touching storage so failures leave it unchanged.
    const parsed = parseProfile(input);
    const displayName = parsed.displayName.kind === 'set' ? parsed.displayName.value : this.profile.displayName;
    const tags = parsed.tags.kind === 'set' ? [...parsed.tags.value] : this.profile.tags;
    this.profile.displayName = displayName;
    this.profile.tags = tags;
    return { displayName, tags: [...tags] };
  }
}
