{
  const fresh = () => new ProfileService({ displayName: 'Name', tags: ['a', 'b'] });
  const snapshot = (s) => JSON.parse(JSON.stringify(s.profile));

  // Empty object is a no-op; null prototype allowed.
  let s = fresh();
  assert.deepEqual(s.patch({}), { displayName: 'Name', tags: ['a', 'b'] });
  assert.deepEqual(s.patch(Object.create(null)), { displayName: 'Name', tags: ['a', 'b'] });

  // Trimming, clearing.
  assert.deepEqual(s.patch({ displayName: '  Bob  ' }), { displayName: 'Bob', tags: ['a', 'b'] });
  assert.deepEqual(s.patch({ displayName: null }), { displayName: null, tags: ['a', 'b'] });
  assert.deepEqual(s.patch({ tags: null }), { displayName: null, tags: [] });
  s = fresh();
  assert.deepEqual(s.patch({ tags: [] }), { displayName: 'Name', tags: [] });
  assert.deepEqual(s.patch({ tags: [' x ', 'y'] }), { displayName: 'Name', tags: ['x', 'y'] });

  // Boundaries.
  s = fresh();
  assert.equal(s.patch({ displayName: 'n'.repeat(40) }).displayName, 'n'.repeat(40));
  assert.deepEqual(s.patch({ tags: ['t'.repeat(12), '2', '3', '4', '5'] }).tags, ['t'.repeat(12), '2', '3', '4', '5']);

  // Invalid inputs leave storage unchanged.
  const invalidInputs = [
    null, undefined, 1, 'x', true, [], [1], new Date(), new (class X {})(), Object.create({}),
    { other: 1 }, { displayName: 'ok', extra: true }, { [Symbol('s')]: 1 },
    { displayName: '' }, { displayName: '   ' }, { displayName: 'n'.repeat(41) }, { displayName: 5 },
    { displayName: undefined }, { tags: undefined }, { tags: 'a' }, { tags: {} }, { tags: [1] }, { tags: ['1', 2] },
    { tags: [''] }, { tags: ['  '] }, { tags: ['a', ' a '] }, { tags: ['1', '2', '3', '4', '5', '6'] },
    { tags: ['t'.repeat(13)] }, { tags: [, 'a'] }, { tags: ['ok'], displayName: '' },
    { displayName: 'ok', tags: ['bad'.repeat(10)] },
  ];
  for (const input of invalidInputs) {
    s = fresh();
    const before = snapshot(s);
    assert.throws(() => s.patch(input), /^Error: invalid profile$/, `expected rejection: ${String(input)}`);
    assert.deepEqual(snapshot(s), before);
  }

  // Getters are not invoked/accepted.
  s = fresh();
  assert.throws(() => s.patch({ get displayName() { return 'x'; } }), /invalid profile/);
  assert.deepEqual(snapshot(s), { displayName: 'Name', tags: ['a', 'b'] });

  // Input not mutated, caller's tags array not reused; result not aliasing storage.
  s = fresh();
  const callerTags = [' a ', 'b'];
  const input = { displayName: ' Z ', tags: callerTags };
  const result = s.patch(input);
  assert.deepEqual(input, { displayName: ' Z ', tags: [' a ', 'b'] });
  assert.notEqual(s.profile.tags, callerTags);
  callerTags.push('c');
  result.tags.push('d');
  assert.deepEqual(s.profile.tags, ['a', 'b']);
}
console.log('public checks passed');
